package com.tutorhub.tutor.service;
import com.tutorhub.common.exception.*;import com.tutorhub.common.pagination.PageResponse;import com.tutorhub.common.security.UserPrincipal;import com.tutorhub.common.storage.FileStorage;import com.tutorhub.tutor.dto.*;import com.tutorhub.tutor.entity.TutorProfile;import com.tutorhub.tutor.repository.TutorProfileRepository;import com.tutorhub.user.entity.Role;import java.io.IOException;import java.math.BigDecimal;import java.sql.ResultSet;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;

@Service public class TutorService {
 private final TutorProfileRepository profiles;private final JdbcTemplate jdbc;private final FileStorage storage;
 public TutorService(TutorProfileRepository p,JdbcTemplate j,FileStorage s){profiles=p;jdbc=j;storage=s;}
 @Transactional(readOnly=true) public TutorProfileResponse me(UserPrincipal p){return out(profile(p));}
 @Transactional public TutorProfileResponse update(UserPrincipal p,TutorProfileRequest r){TutorProfile x=profile(p);x.setHeadline(r.headline());x.setBio(r.bio());x.setEducationLevel(r.educationLevel());x.setSchool(r.school());x.setMajor(r.major());x.setYearsExperience(r.yearsExperience());x.setHourlyRate(r.hourlyRate());x.setTeachingMode(r.teachingMode());x.setDistrictId(r.districtId());return out(x);}
 @Transactional(readOnly=true) public List<TutorSubjectResponse> subjects(UserPrincipal p){profile(p);return subjects(p.id());}
 @Transactional public List<TutorSubjectResponse> subjects(UserPrincipal p,List<TutorSubjectRequest> rows){profile(p);if(rows==null||rows.isEmpty())throw new BusinessRuleException("SUBJECTS_REQUIRED","At least one subject is required");for(var r:rows){if(!r.validRange())throw new BusinessRuleException("INVALID_GRADE_RANGE","gradeTo must be at least gradeFrom");if(jdbc.queryForObject("select count(*) from subjects where id=? and active",Integer.class,r.subjectId())==0)throw new NotFoundException("Subject not found");}jdbc.update("delete from tutor_subjects where tutor_id=?",p.id());for(var r:rows)jdbc.update("insert into tutor_subjects(tutor_id,subject_id,grade_from,grade_to) values(?,?,?,?)",p.id(),r.subjectId(),r.gradeFrom(),r.gradeTo());return subjects(p.id());}
 @Transactional(readOnly=true) public List<AvailabilitySlotResponse> availability(UserPrincipal p){profile(p);return availability(p.id());}
 @Transactional public List<AvailabilitySlotResponse> availability(UserPrincipal p,List<AvailabilitySlotRequest> rows){profile(p);if(rows==null)throw new BusinessRuleException("INVALID_AVAILABILITY","Availability is required");for(var r:rows)if(!r.endTime().isAfter(r.startTime()))throw new BusinessRuleException("INVALID_AVAILABILITY","endTime must be after startTime");jdbc.update("delete from tutor_availability where tutor_id=?",p.id());for(var r:rows)jdbc.update("insert into tutor_availability(tutor_id,day_of_week,start_time,end_time) values(?,?,?,?)",p.id(),r.dayOfWeek(),r.startTime(),r.endTime());return availability(p.id());}
 @Transactional(readOnly=true) public List<TutorDocumentResponse> documents(UserPrincipal p){profile(p);return documents(p.id());}
 @Transactional public TutorDocumentResponse upload(UserPrincipal p,String type,MultipartFile f){profile(p);if(!Set.of("ID_CARD","DEGREE","STUDENT_CARD","CERTIFICATE").contains(type))throw new BusinessRuleException("INVALID_DOCUMENT_TYPE","Invalid document type");String mime=f.getContentType();if(f.isEmpty()||!Set.of("application/pdf","image/jpeg","image/png").contains(mime))throw new BusinessRuleException("INVALID_DOCUMENT","Document must be PDF, JPEG, or PNG");try{String key=storage.store("tutors/"+p.id()+"/documents/"+UUID.randomUUID(),f.getInputStream(),f.getSize(),mime);Long id=jdbc.queryForObject("insert into tutor_documents(tutor_id,doc_type,storage_key) values(?,?,?) returning id",Long.class,p.id(),type,key);return documents(p.id()).stream().filter(x->x.id().equals(id)).findFirst().orElseThrow();}catch(IOException e){throw new BusinessRuleException("INVALID_DOCUMENT","Could not read document");}}
 @Transactional public void deleteDocument(UserPrincipal p,long id){profile(p);String key=jdbc.query("select storage_key from tutor_documents where id=? and tutor_id=?",rs->rs.next()?rs.getString(1):null,id,p.id());if(key==null)throw new NotFoundException("Document not found");storage.delete(key);jdbc.update("delete from tutor_documents where id=?",id);}
 @Transactional public void submit(UserPrincipal p){TutorProfile x=profile(p);if(!Set.of("DRAFT","REJECTED").contains(x.getVerificationStatus()))throw new BusinessRuleException("INVALID_SUBMISSION","Profile cannot be submitted now");if(blank(x.getHeadline())||blank(x.getEducationLevel())||blank(x.getSchool())||x.getHourlyRate()<=0||subjects(p.id()).isEmpty()||jdbc.queryForObject("select count(*) from tutor_documents where tutor_id=? and doc_type='ID_CARD'",Integer.class,p.id())==0)throw new BusinessRuleException("PROFILE_INCOMPLETE","Profile, subject, and ID document are required");x.setVerificationStatus("PENDING");}
 @Transactional(readOnly=true) public PageResponse<TutorCardResponse> search(Integer subject,Short grade,Integer district,String mode,Long minRate,Long maxRate,BigDecimal minRating,String q,String sort,int page,int size){String order=switch(sort==null?"newest":sort){case "rating"->"p.rating_avg desc,p.rating_count desc";case "rate"->"p.hourly_rate asc";default->"p.created_at desc";};StringBuilder w=new StringBuilder(" where p.verification_status='VERIFIED'");List<Object>a=new ArrayList<>();if(subject!=null){w.append(" and exists(select 1 from tutor_subjects ts where ts.tutor_id=p.user_id and ts.subject_id=?");a.add(subject);if(grade!=null){w.append(" and ? between ts.grade_from and ts.grade_to");a.add(grade);}w.append(")");}if(district!=null){w.append(" and p.district_id=?");a.add(district);}if(mode!=null){w.append(" and p.teaching_mode in (?,'BOTH')");a.add(mode);}if(minRate!=null){w.append(" and p.hourly_rate>=?");a.add(minRate);}if(maxRate!=null){w.append(" and p.hourly_rate<=?");a.add(maxRate);}if(minRating!=null){w.append(" and p.rating_avg>=?");a.add(minRating);}if(q!=null&&!q.isBlank()){w.append(" and p.search_vector @@ plainto_tsquery('simple',?)");a.add(q);}long total=jdbc.queryForObject("select count(*) from tutor_profiles p"+w,Long.class,a.toArray());var b=new ArrayList<>(a);b.add(size);b.add(page*size);var rows=jdbc.query("select p.user_id,u.full_name,p.headline,p.hourly_rate,p.teaching_mode,p.district_id,p.rating_avg,p.rating_count,p.created_at from tutor_profiles p join users u on u.id=p.user_id"+w+" order by "+order+" limit ? offset ?",this::card,b.toArray());return new PageResponse<>(rows,page,size,total,(int)Math.ceil((double)total/size));}
 @Transactional(readOnly=true) public TutorPublicResponse publicProfile(long id){TutorPublicResponse x=jdbc.query("select p.user_id,u.full_name,p.headline,p.bio,p.education_level,p.school,p.major,p.years_experience,p.hourly_rate,p.teaching_mode,p.district_id,p.rating_avg,p.rating_count from tutor_profiles p join users u on u.id=p.user_id where p.user_id=? and p.verification_status='VERIFIED'",rs->rs.next()?pub(rs):null,id);if(x==null)throw new NotFoundException("Tutor not found");return x;}
 @Transactional(readOnly=true) public List<AvailabilitySlotResponse> publicAvailability(long id,LocalDate date){verified(id);List<AvailabilitySlotResponse> weekly=jdbc.query("select id,day_of_week,start_time,end_time from tutor_availability where tutor_id=? and day_of_week=? order by start_time",(rs,n)->new AvailabilitySlotResponse(rs.getLong(1),rs.getShort(2),rs.getObject(3,LocalTime.class),rs.getObject(4,LocalTime.class)),id,date.getDayOfWeek().getValue());Instant dayStart=date.atStartOfDay(ZoneId.of("Asia/Ho_Chi_Minh")).toInstant(),dayEnd=date.plusDays(1).atStartOfDay(ZoneId.of("Asia/Ho_Chi_Minh")).toInstant();var bookings=jdbc.query("select start_at,end_at from bookings where tutor_id=? and status in ('PENDING','CONFIRMED') and start_at<? and end_at>?",(rs,n)->new Instant[]{rs.getObject(1,Instant.class),rs.getObject(2,Instant.class)},id,dayEnd,dayStart);List<AvailabilitySlotResponse> result=new ArrayList<>();for(var slot:weekly){List<LocalTime[]> free=new ArrayList<>();free.add(new LocalTime[]{slot.startTime(),slot.endTime()});for(var booking:bookings){LocalTime start=booking[0].atZone(ZoneId.of("Asia/Ho_Chi_Minh")).toLocalTime(),end=booking[1].atZone(ZoneId.of("Asia/Ho_Chi_Minh")).toLocalTime();List<LocalTime[]> next=new ArrayList<>();for(var range:free){if(!start.isBefore(range[1])||!end.isAfter(range[0]))next.add(range);else{if(start.isAfter(range[0]))next.add(new LocalTime[]{range[0],start});if(end.isBefore(range[1]))next.add(new LocalTime[]{end,range[1]});}}free=next;}for(var range:free)if(range[0].isBefore(range[1]))result.add(new AvailabilitySlotResponse(slot.id(),slot.dayOfWeek(),range[0],range[1]));}return result;}
 @Transactional(readOnly=true) public PageResponse<TutorReviewResponse> reviews(long id,int page,int size){verified(id);long total=jdbc.queryForObject("select count(*) from reviews where tutor_id=? and visible",Long.class,id);var rows=jdbc.query("select id,rating,comment,reply,created_at from reviews where tutor_id=? and visible order by created_at desc limit ? offset ?",(rs,n)->new TutorReviewResponse(rs.getLong(1),rs.getShort(2),rs.getString(3),rs.getString(4),rs.getObject(5,Instant.class)),id,size,page*size);return new PageResponse<>(rows,page,size,total,(int)Math.ceil((double)total/size));}
 @Transactional(readOnly=true) public PageResponse<TutorProfileResponse> pending(int page,int size){long t=jdbc.queryForObject("select count(*) from tutor_profiles where verification_status='PENDING'",Long.class);var r=jdbc.query("select p.user_id,u.full_name,p.headline,p.bio,p.education_level,p.school,p.major,p.years_experience,p.hourly_rate,p.teaching_mode,p.district_id,p.verification_status from tutor_profiles p join users u on u.id=p.user_id where p.verification_status='PENDING' order by p.updated_at limit ? offset ?",(rs,n)->profileRow(rs),size,page*size);return new PageResponse<>(r,page,size,t,(int)Math.ceil((double)t/size));}
 @Transactional(readOnly=true) public TutorProfileResponse adminDetail(long id){var x=jdbc.query("select p.user_id,u.full_name,p.headline,p.bio,p.education_level,p.school,p.major,p.years_experience,p.hourly_rate,p.teaching_mode,p.district_id,p.verification_status from tutor_profiles p join users u on u.id=p.user_id where p.user_id=?",rs->rs.next()?profileRow(rs):null,id);if(x==null)throw new NotFoundException("Tutor not found");return x;}
 @Transactional public void verify(long id){if(jdbc.update("update tutor_profiles set verification_status='VERIFIED',verified_at=now(),reject_reason=null where user_id=? and verification_status='PENDING'",id)==0)throw new BusinessRuleException("INVALID_TUTOR_STATUS","Tutor is not pending");}
 @Transactional public void reject(long id,String reason){if(blank(reason))throw new BusinessRuleException("REJECT_REASON_REQUIRED","A rejection reason is required");if(jdbc.update("update tutor_profiles set verification_status='REJECTED',reject_reason=? where user_id=? and verification_status='PENDING'",reason,id)==0)throw new BusinessRuleException("INVALID_TUTOR_STATUS","Tutor is not pending");}
 @Transactional public void reviewDocument(long id,String status,String reason){if("REJECTED".equals(status)&&blank(reason))throw new BusinessRuleException("REJECT_REASON_REQUIRED","A rejection reason is required");if(jdbc.update("update tutor_documents set status=?,reviewed_at=now(),reject_reason=? where id=? and status='PENDING'",status,reason,id)==0)throw new NotFoundException("Pending document not found");}
 private TutorProfile profile(UserPrincipal p){if(p.role()!=Role.TUTOR)throw new ForbiddenException("Tutor role required");return profiles.findById(p.id()).orElseThrow(()->new NotFoundException("Tutor profile not found"));}private void verified(long id){if(jdbc.queryForObject("select count(*) from tutor_profiles where user_id=? and verification_status='VERIFIED'",Integer.class,id)==0)throw new NotFoundException("Tutor not found");}private List<TutorSubjectResponse> subjects(long id){return jdbc.query("select ts.subject_id,s.name,ts.grade_from,ts.grade_to from tutor_subjects ts join subjects s on s.id=ts.subject_id where ts.tutor_id=? order by s.name",(rs,n)->new TutorSubjectResponse(rs.getInt(1),rs.getString(2),rs.getShort(3),rs.getShort(4)),id);}private List<AvailabilitySlotResponse> availability(long id){return jdbc.query("select id,day_of_week,start_time,end_time from tutor_availability where tutor_id=? order by day_of_week,start_time",(rs,n)->new AvailabilitySlotResponse(rs.getLong(1),rs.getShort(2),rs.getObject(3,LocalTime.class),rs.getObject(4,LocalTime.class)),id);}private List<TutorDocumentResponse> documents(long id){return jdbc.query("select id,doc_type,status,storage_key,created_at from tutor_documents where tutor_id=? order by created_at desc",(rs,n)->new TutorDocumentResponse(rs.getLong(1),rs.getString(2),rs.getString(3),storage.presignedGet(rs.getString(4)),rs.getObject(5,Instant.class)),id);}private TutorProfileResponse out(TutorProfile x){return new TutorProfileResponse(x.getUserId(),x.getUser().getFullName(),x.getHeadline(),x.getBio(),x.getEducationLevel(),x.getSchool(),x.getMajor(),x.getYearsExperience(),x.getHourlyRate(),x.getTeachingMode(),x.getDistrictId(),x.getVerificationStatus());}private TutorCardResponse card(ResultSet r,int n)throws java.sql.SQLException{return new TutorCardResponse(r.getLong(1),r.getString(2),r.getString(3),r.getLong(4),r.getString(5),(Integer)r.getObject(6),r.getBigDecimal(7),r.getInt(8),r.getObject(9,Instant.class));}private TutorPublicResponse pub(ResultSet r)throws java.sql.SQLException{long id=r.getLong(1);return new TutorPublicResponse(id,r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getShort(8),r.getLong(9),r.getString(10),(Integer)r.getObject(11),r.getBigDecimal(12),r.getInt(13),subjects(id));}private TutorProfileResponse profileRow(ResultSet r)throws java.sql.SQLException{return new TutorProfileResponse(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getShort(8),r.getLong(9),r.getString(10),(Integer)r.getObject(11),r.getString(12));}private boolean blank(String s){return s==null||s.isBlank();}
}
